#!/usr/bin/env bash
# Publish whoobe.dev and docs.whoobe.dev on Cloudflare Pages (two static projects, uploaded directly: no Git integration, no build on
# Cloudflare). Run from anywhere in the repository:
#
#   scripts/site/pages/deploy.sh home [--no-deploy]   the homepage (scripts/site/pages/home, {{VERSION}} = package.json, {{DOCS_URL}} = $DOCS_URL) -> project whoobe-dev
#   scripts/site/pages/deploy.sh docs [--no-deploy]   the documentation site generated by whoobe-publish --kind docs  -> project whoobe-docs
#
# --no-deploy only writes the folder (sites/pages-home, sites/pages-docs) to look at it first (`npx serve sites/pages-docs`).
#
# docs needs a running Whoobe that holds the documentation site "whoobe docs release" (the folder docs/release uploaded to the DAM,
# docs/release/README.md); only the generation reads it, the published site does not depend on it (the images are copied):
#   DOCS_API_URL      the CMS API (core-api)                  default http://localhost:3003
#   DOCS_WEBSITE_ID   the UUID of the documentation website   required (Settings > Websites, or the Publish tab)
#
# Cloudflare: Node 20+, `npx wrangler login` once (or CLOUDFLARE_API_TOKEN with "Cloudflare Pages: Edit" + CLOUDFLARE_ACCOUNT_ID for CI).
# The first time, create the projects:  npx wrangler pages project create whoobe-dev --production-branch main  (and whoobe-docs),
# then attach the domains in the dashboard (Workers & Pages > project > Custom domains): whoobe.dev (+ www) and docs.whoobe.dev.
# HOME_PROJECT / DOCS_PROJECT change the project names, WRANGLER the command (default: npx --yes wrangler).
set -euo pipefail

ROOT="$(git -C "$(dirname "$0")" rev-parse --show-toplevel)"
cd "$ROOT"
WHAT="${1:-}"; DEPLOY=1
[ "${2:-}" = "--no-deploy" ] && DEPLOY=0
VERSION="$(sed -nE 's/^  "version": "([^"]+)".*/\1/p' package.json | head -1)"
REPO_URL="https://github.com/swina/whoobe_project"
WRANGLER="${WRANGLER:-npx --yes wrangler}"

deploy() {  # <folder> <project>
  [ "$DEPLOY" = 1 ] || { echo ">>> written to $1 (not deployed)"; return; }
  echo ">>> uploading $1 to the Cloudflare Pages project $2 ..."
  # --branch main = the production deployment; --commit-hash ties it to the checkout it was made from
  $WRANGLER pages deploy "$1" --project-name "$2" --branch main \
    --commit-hash "$(git rev-parse HEAD)" --commit-message "whoobe v$VERSION ($(git rev-parse --short HEAD))" --commit-dirty=true
}

case "$WHAT" in
  home)
    OUT="$ROOT/sites/pages-home"
    rm -rf "$OUT"; mkdir -p "$OUT"
    cp -R scripts/site/pages/home/. "$OUT/"
    # DOCS_URL: where the documentation links go; the docs in the repository until docs.whoobe.dev is published
    DOCS_URL="${DOCS_URL:-$REPO_URL/blob/master/docs/release/README.md}"
    sed -i.bak -e "s/{{VERSION}}/$VERSION/g" -e "s#{{DOCS_URL}}#$DOCS_URL#g" "$OUT/index.html" "$OUT/404.html" && rm -f "$OUT"/*.bak
    deploy "$OUT" "${HOME_PROJECT:-whoobe-dev}"
    ;;
  docs)
    : "${DOCS_WEBSITE_ID:?set DOCS_WEBSITE_ID to the UUID of the documentation website}"
    API="${DOCS_API_URL:-http://localhost:3003}"
    curl -fsS "$API/health" >/dev/null || { echo "the CMS does not answer at $API/health (DOCS_API_URL)" >&2; exit 1; }
    OUT="$ROOT/sites/pages-docs"
    echo ">>> building the publisher ..."
    pnpm run --silent --filter "@whoobe-cms/publish..." build >/dev/null
    echo ">>> generating the documentation site of v$VERSION from $API ..."
    # --strict: a broken link stops here, before anything is uploaded. The generator removes the pages that no longer exist.
    node packages/publish/bin/whoobe-publish.js --kind docs --strict \
      --api-url "$API" --website-id "$DOCS_WEBSITE_ID" --out-dir "$OUT" \
      --base-path / --site-url https://docs.whoobe.dev \
      --version-label "v$VERSION" --version-url "$REPO_URL/releases/tag/v$VERSION" --repo-url "$REPO_URL"
    cat > "$OUT/_headers" <<'EOF'
/*
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin
  X-Frame-Options: DENY
  Permissions-Policy: camera=(), microphone=(), geolocation=()
EOF
    deploy "$OUT" "${DOCS_PROJECT:-whoobe-docs}"
    ;;
  *) echo "usage: scripts/site/pages/deploy.sh home|docs [--no-deploy]" >&2; exit 1 ;;
esac
